/* Pausa v1.9.0: local generative catalog composition; explicit inference failures. */
'use strict';
const Core=window.PausaCore;
const STORAGE='pausa.local.v1';
let state;
try{state=Core.normalize(JSON.parse(localStorage.getItem(STORAGE)||'null'))}catch{state=Core.normalize(null)}
let page=['inicio','agente','rutinas','biblioteca','actividad','ajustes'].includes(location.hash.slice(1))?location.hash.slice(1):'inicio',filter='todos',safetyAction=null,activeModal='',lastToast='',lastDueNotificationAt=0;
const LIBRARY=Object.freeze(window.PAUSA_LIBRARY||[]);
let libraryQuery='', libraryFilter='Todas', librarySide='todos', libraryShown=24, libraryPlaying=new Set(), librarySelected=null, libraryPreviewPlaying=false, offlineAbort=false, offlineLoading=false;
let mediaAnimated=!(window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches);
const el=(id)=>document.getElementById(id);
const now=()=>Date.now();
const persist=()=>{try{localStorage.setItem(STORAGE,JSON.stringify(state))}catch{notifyToast('No se pudo guardar','El almacenamiento de este navegador está deshabilitado.')}};
const esc=(s)=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dateFmt=(stamp)=>new Intl.DateTimeFormat('es-PE',{day:'numeric',month:'short'}).format(new Date(stamp));
const timeFmt=(stamp)=>new Intl.DateTimeFormat('es-PE',{hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(stamp));
const totalSeconds=(routine)=>routine.ids.reduce((n,id)=>n+EXERCISES[id].seconds,0);
const duration=(seconds)=>`${Core.minutes(seconds)} min`;

/* All media are original local PNG/GIF assets. Motion is optional and never required to understand a movement. */
const GUIDED_HQ_MEDIA=Object.freeze({pelvicFloor:'pelvic-tilt',catCow:'cat-cow',knees:'knee-rolls',bridge:'glute-bridge',birdDog:'bird-dog'});
function guidedMedia(id){const mediaId=EXERCISES[id]?.mediaId||GUIDED_HQ_MEDIA[id];return mediaId?LIBRARY.find(item=>item.id===mediaId)||null:null;}
function exerciseMedia(id, animated=false, eager=false){
 const e=EXERCISES[id];if(!e)return '';
 const useNew=guidedMedia(id);
 const format=(animated&&mediaAnimated)?'gif':'png';
 const loading=eager?'eager':'lazy';
 return `<img class="exercise-media-image" src="${useNew?(format==='gif'?useNew.gif:useNew.poster):`assets/exercises/${id}.${format}`}" data-media-id="${id}" alt="Ilustración orientativa de ${esc(e.name)}; lee las instrucciones antes de realizarlo" loading="${loading}" decoding="async" width="${useNew?640:480}" height="${useNew?640:320}">`;
}
function motionControl(){return `<button type="button" class="media-motion-toggle" data-action="toggle-media" aria-pressed="${mediaAnimated}" aria-label="${mediaAnimated?'Detener':'Reproducir'} la animación">${icon(mediaAnimated?'pause':'play',14)} ${mediaAnimated?'Pausar GIF':'Ver movimiento'}</button>`}
function visualExercise(id, showMotion=true){return `<div class="exercise-visual">${exerciseMedia(id,showMotion,true)}${showMotion?motionControl():''}<span class="visual-guide-label">Ilustración orientativa · Sigue los pasos</span></div>`}
function toggleMedia(){mediaAnimated=!mediaAnimated;
 document.querySelectorAll('#modalRoot .exercise-media-image').forEach(img=>{const id=img.dataset.mediaId;if(!EXERCISES[id])return;img.src=(() => {const a=guidedMedia(id);return a?(mediaAnimated?a.gif:a.poster):`assets/exercises/${id}.${mediaAnimated?'gif':'png'}`})()});
 document.querySelectorAll('#modalRoot .media-motion-toggle').forEach(button=>{button.setAttribute('aria-pressed',String(mediaAnimated));button.setAttribute('aria-label',mediaAnimated?'Detener la animación':'Reproducir la animación');button.innerHTML=`${icon(mediaAnimated?'pause':'play',14)} ${mediaAnimated?'Pausar GIF':'Ver movimiento'}`});
}
function heroArt(){return `<svg viewBox="0 0 290 320" aria-hidden="true"><ellipse cx="147" cy="305" rx="119" ry="12" fill="#0b3d34" opacity=".25"/><path d="M219 140h54v11h-54zM223 151h8v148h-8M260 151h7v148h-7" fill="#a4c0ae"/><rect x="220" y="119" width="43" height="28" rx="6" fill="#e7f5d2"/><path d="M228 125h26v3h-26zM228 131h22v3h-22z" fill="#75ad8b"/><path d="M20 263c-6-43 16-49 27-21-1-40 28-44 30-11-7-49 37-57 40-15l-11 89H45z" fill="#8bbb99"/><rect x="34" y="275" width="81" height="30" rx="6" fill="#e5d5bc"/><path d="M126 177c9-10 22-6 26 5l8 23 43 4 21-30 10 7-22 44-58-3-22-31z" fill="#e4f0cd"/><circle cx="121" cy="143" r="23" fill="#c79071"/><path d="M99 142c-2-28 38-38 47-6-8 2-13-1-20-7-4 12-14 14-27 13" fill="#20382e"/><path d="M142 159c17-2 36 7 36 25l-4 74-61 0-5-72c0-15 14-24 34-27" fill="#e2edd6"/><path d="M121 192l-32 29 22 35" fill="none" stroke="#c79071" stroke-width="15" stroke-linecap="round"/><path d="M173 188 204 207 221 180" fill="none" stroke="#c79071" stroke-width="15" stroke-linecap="round"/><path d="M119 256h58l20 42h-32l-21-24-13 24H99z" fill="#34483f"/><path d="M120 298h-29M197 298h-34" stroke="#e8edce" stroke-width="8" stroke-linecap="round"/><path d="M198 84c5-15 24-11 28-1 8-12 26-5 27 7 0 15-17 23-30 37-14-13-31-26-25-43" fill="#c4d9b2" opacity=".88"/><path d="M225 92v22m-11-11h22" stroke="#62967a" stroke-width="4" stroke-linecap="round"/></svg>`}
function statsToday(){const today=Core.dayLogs(state.logs,Core.dateKey(now()));return {count:today.length,minutes:Core.sumMinutes(today),streak:Core.streak(state.logs)}}
function routineCard(r){const preview={express:'side-raise-bilateral',desk:'shoulder-backward-bilateral',lumbar:'cat-cow',strength:'glute-bridge'};const x=LIBRARY.find(x=>x.id===preview[r.id])||guidedMedia(r.ids[0]);return `<button type="button" class="routine-card tone-${r.tone}" data-action="detail" data-routine="${r.id}" aria-label="Ver rutina ${esc(r.name)}"><span class="routine-art">${x?`<img src="${x.poster}" alt="" loading="lazy" width="640" height="640">`:exerciseMedia(r.ids[0])}<span class="routine-duration">${icon('clock',13)} ${duration(totalSeconds(r))}</span><span class="routine-open">${icon('arrow',18)}</span></span><span class="routine-main"><span class="routine-badge">${icon(r.icon,14)} ${esc(r.badge)}</span><h3>${esc(r.name)}</h3><p>${esc(r.description)}</p><span class="routine-meta">${icon('activity',13)} ${esc(r.level)} <span>·</span> ${r.ids.length} movimientos</span></span></button>`}
function statusBanner(){return state.safety==='urgent'?`<div class="status-banner" role="alert"><b>Atención urgente:</b> señalaste síntomas de alarma. No inicies rutinas; busca evaluación médica urgente. <button class="link-action" data-action="safety">Revisar respuestas</button></div>`:state.safety==='caution'?`<div class="status-banner"><b>Precaución:</b> el dolor que baja a la pierna o persiste merece evaluación profesional. Elige movimiento suave y detente si empeoras. <button class="link-action" data-action="safety">Revisar</button></div>`:''}
function home(){const t=statsToday(),r=state.reminders;return `<section class="heading-row home-heading"><div><div class="eyebrow">TU MOMENTO, TODOS LOS DÍAS</div><h1>Qué bien que estés aquí<span>.</span></h1><p class="subheading">Baja el ritmo un momento. Tu próxima pausa empieza contigo.</p></div><button class="button secondary heading-action" data-action="safety">${icon('shield',16)} Antes de empezar</button></section>${statusBanner()}
 <div class="home-grid"><section class="hero"><div class="hero-text"><span class="hero-label"><span class="hero-star">✳</span> UN POCO DE MOVIMIENTO, MUCHO PARA TI</span><h2>Haz espacio para<br><em>sentirte mejor.</em></h2><p>Una pausa breve entre pantallas, reuniones y pendientes. Sin equipo. A tu ritmo.</p><button class="button" data-action="detail" data-routine="seated">${icon('play',17)} Hacer una pausa <span class="cta-arrow">${icon('arrow',18)}</span></button><div class="hero-footnote">${icon('clock',14)} ${duration(totalSeconds(ROUTINES.find(r=>r.id==='seated')))} para ti <span>·</span> Sin exigencias</div></div><div class="hero-art"><div class="hero-orbit"></div><img src="${LIBRARY.find(x=>x.id==='seated-overhead-bilateral')?.poster||LIBRARY[0].poster}" width="640" height="640" alt="Persona ilustrada elevando los brazos suavemente mientras permanece sentada"><span class="floating-note">${icon('activity',17)} Un movimiento a la vez</span><span class="hero-art-star" aria-hidden="true">✳</span></div></section>
 <section class="reminder-card"><div class="card-top"><div class="card-heading">${icon('clock',19)} Tu próximo respiro</div><span class="status-pill ${r.pending?'due':r.enabled?'on':''}" id="reminderStatus">${r.pending?'Ahora':r.enabled?'Activo':'A tu ritmo'}</span></div><div class="timer-center"><div class="timer-ring"><div><div id="countdown" class="timer-number" aria-label="Tiempo hasta la próxima pausa">${r.enabled?(r.pending?'00:00':Core.formatClock(Math.ceil((r.nextDueAt-now())/1000))):'--:--'}</div><div class="timer-caption">${r.pending?'Es momento de moverte':r.enabled?'hasta tu siguiente pausa':'Tu tiempo también importa'}</div></div></div></div><div class="timer-controls">${r.pending?`<button class="button primary" data-action="detail" data-routine="seated">${icon('play',16)} Hacer pausa</button><button class="button secondary" data-action="snooze">+10 min</button>`:r.enabled?`<button class="button secondary" data-action="reminders-off">${icon('pause',16)} Detener</button><button class="button primary" data-action="detail" data-routine="seated">Moverme ${icon('arrow',15)}</button>`:`<button class="button primary" data-action="reminders-on">${icon('bell',16)} Recordarme hacer una pausa</button>`}</div><p class="reminder-note">${r.enabled?`Cada ${r.interval} minutos · Con Pausa abierta`:'Tú eliges la frecuencia. Con Pausa abierta.'}</p></section></div>
 <section class="zone-discovery"><div><span class="eyebrow">ESCUCHA A TU CUERPO</span><h2>¿Qué zona quieres mover?</h2></div><div class="home-zone-list">${[['lumbar','Espalda'],['cuello','Cuello'],['hombros','Hombros'],['manos','Manos'],['piernas','Piernas'],['general','Todo el cuerpo']].map(([z,l])=>`<button type="button" class="home-zone" data-guide-zone="${z}"><span class="zone-symbol" aria-hidden="true">${zoneSymbol(z)}</span>${l}${icon('arrow',14)}</button>`).join('')}</div></section>
 <div class="section-title-row"><div><div class="eyebrow">SIN PRISA. SIN COMPLICACIONES.</div><h2>Un momento para ti</h2><p class="subtext">Elige una pausa que encaje con tu día.</p></div><button class="link-action" data-nav="rutinas">Todas las rutinas ${icon('arrow',15)}</button></div>
 <div class="routine-grid">${ROUTINES.map(routineCard).join('')}</div>
 <div class="section-title-row progress-heading"><div><h2>Cada pausa cuenta</h2><p class="subtext">Tu constancia, paso a paso.</p></div><button class="link-action" data-nav="actividad">Mi actividad ${icon('arrow',15)}</button></div><div class="mini-stat-grid"><div class="stat-card"><span class="stat-icon">${icon('check',18)}</span><div><div class="stat-value">${t.count}</div><p class="stat-label">Pausas hoy</p></div></div><div class="stat-card"><span class="stat-icon">${icon('clock',18)}</span><div><div class="stat-value">${t.minutes}<span>min</span></div><p class="stat-label">Movimiento hoy</p></div></div><div class="stat-card"><span class="stat-icon">${icon('spark',18)}</span><div><div class="stat-value">${t.streak}<span>${t.streak===1?'día':'días'}</span></div><p class="stat-label">Tu racha actual</p></div></div></div>
 <div class="info-bar">${icon('shield',18)}<span>Muévete solo si te resulta cómodo. Si aparece o aumenta el dolor, detente. Pausa es una herramienta de bienestar y no reemplaza una valoración médica.</span></div>`}
function zoneSymbol(z){const paths={lumbar:'M12 3v18M8 5c-5 4-5 10 0 14M16 5c5 4 5 10 0 14M8 10h8M8 14h8',cuello:'M9 3a3 3 0 0 0 6 0M9 8v4l-5 3v5h16v-5l-5-3V8',hombros:'M9 3h6v5l6 4v8M3 20v-8l6-4M3 13h5M16 13h5',manos:'M7 12V6a1.5 1.5 0 0 1 3 0v5-7a1.5 1.5 0 0 1 3 0v7-6a1.5 1.5 0 0 1 3 0v7-3a1.5 1.5 0 0 1 3 0v8c0 4-9 6-11 3l-5-6c-1-2 1-3 2-2l2 2',piernas:'M8 3l-1 9-3 8h5l3-8 3 8h5l-3-9-1-8M7 12h10',general:'M9 4a3 3 0 1 0 6 0 3 3 0 0 0-6 0M3 10l9 2 9-2M12 12v4M7 22l5-6 5 6'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round">${paths[z]?`<path d="${paths[z]}"/>`:''}</svg>`}
function routinesPage(){const visible=filter==='todos'?ROUTINES:ROUTINES.filter(r=>r.category===filter);return `<section class="page-head"><div class="eyebrow">A TU PROPIO RITMO</div><h1>Muévete como te sienta bien.</h1><p class="subheading">Rutinas breves y originales, pensadas para quienes trabajan sentados.</p></section>${statusBanner()}<div class="filters">${[['todos','Todas'],['escritorio','En mi escritorio'],['movilidad','Movilidad'],['fuerza','Fuerza suave']].map(([id,name])=>`<button class="filter ${filter===id?'active':''}" data-filter="${id}">${name}</button>`).join('')}</div><div class="routines-page-grid">${visible.map(routineCard).join('')}</div><div class="info-bar">${icon('shield',18)}<span>Estas secuencias no son tratamiento individualizado ni reemplazan a un fisioterapeuta. No hagas movimientos dolorosos. Ante síntomas de alarma busca atención urgente.</span></div>`}
function filteredLibrary(){
 const q=libraryQuery.trim().toLocaleLowerCase('es');
 return LIBRARY.filter(x=>(libraryFilter==='Todas'||x.category===libraryFilter)&&(librarySide==='todos'||x.side===librarySide)&&(!q||`${x.title} ${x.category} ${x.id}`.toLocaleLowerCase('es').includes(q)));
}
function libraryCard(x){const playing=libraryPlaying.has(x.id)&&mediaAnimated;return `<article class="library-card" data-library-id="${esc(x.id)}"><button type="button" class="library-image" data-action="library-detail" data-id="${esc(x.id)}" aria-label="Explorar ${esc(x.title)}"><img src="${playing?x.gif:x.poster}" loading="lazy" decoding="async" width="640" height="640" alt="Demostración ilustrativa de ${esc(x.title)}"><span class="library-image-overlay">${icon('zoom',15)} Ver detalle</span></button><div class="library-info"><div class="library-kicker"><span>${esc(x.category)}</span><span>#${String(x.index).padStart(3,'0')}</span></div><h3>${esc(x.title)}</h3><div class="library-card-actions"><button class="library-play" type="button" data-action="library-toggle" data-id="${esc(x.id)}" aria-pressed="${playing}">${icon(playing?'pause':'play',15)} ${playing?'Detener GIF':'Ver GIF'}</button><button class="library-icon-action" type="button" data-action="library-detail" data-id="${esc(x.id)}" aria-label="Información de ${esc(x.title)}">${icon('arrow',15)}</button></div></div></article>`}
function libraryPage(){const available=filteredLibrary(),shown=available.slice(0,libraryShown),categories=['Todas',...new Set(LIBRARY.map(x=>x.category))];return `<section class="page-head"><div class="eyebrow">UN MOVIMIENTO A LA VEZ</div><h1>Biblioteca de movimiento.</h1><p class="subheading">${LIBRARY.length} animaciones originales para explorar pausas activas de cuerpo completo.</p></section><div class="library-intro"><div><strong>${icon('spark',17)} Explora con calma.</strong><p>Las ilustraciones muestran movimientos orientativos. Su técnica, seguridad y pertinencia clínica no han sido certificadas; no son prescripciones de ejercicio ni sustituyen una evaluación profesional.</p></div><span class="library-total">${LIBRARY.length}<small>GIF incluidos</small></span></div>${statusBanner()}<div class="library-toolbar"><label class="library-search-label" for="librarySearch">Buscar un movimiento<input id="librarySearch" type="search" placeholder="Ej. hombros, tobillos, gato-vaca…" value="${esc(libraryQuery)}" autocomplete="off"></label><label class="library-side-label" for="librarySide">Variación<select id="librarySide"><option value="todos" ${librarySide==='todos'?'selected':''}>Todos los lados</option><option value="bilateral" ${librarySide==='bilateral'?'selected':''}>Ambos lados</option><option value="left" ${librarySide==='left'?'selected':''}>Izquierdo</option><option value="right" ${librarySide==='right'?'selected':''}>Derecho</option></select></label></div><div class="library-filter-wrap" aria-label="Filtrar por zona">${categories.map(cat=>`<button type="button" class="filter ${libraryFilter===cat?'active':''}" data-library-filter="${esc(cat)}" aria-pressed="${libraryFilter===cat}">${esc(cat)}</button>`).join('')}</div><div class="library-list-top"><strong><span id="libraryCount">${available.length}</span> movimientos encontrados</strong><button type="button" class="link-action" data-action="library-pause-all">${icon('pause',15)} Detener animaciones</button></div><div id="libraryResults">${shown.length?`<div class="library-grid">${shown.map(libraryCard).join('')}</div>${available.length>shown.length?`<div class="library-more"><button class="button secondary" type="button" data-action="library-more">Mostrar más (${available.length-shown.length} restantes)</button></div>`:''}`:`<div class="library-empty"><strong>Sin resultados</strong><p>Prueba otra zona o palabra clave.</p><button class="button secondary" type="button" data-action="library-clear">Limpiar filtros</button></div>`}</div><div class="library-offline panel"><div><strong>${icon('download',17)} Biblioteca sin conexión</strong><p>Los 112 GIF se incluyen en la distribución. Si instalas Pausa desde una web, se descargan al reproducirse. Puedes guardarlos todos en el almacenamiento de este navegador, siempre que haya espacio disponible.</p><small id="offlineProgress" role="status">La descarga completa es opcional (aprox. 124 MB entre GIF y PNG).</small></div><div class="library-offline-buttons"><button class="button secondary" type="button" data-action="library-offline" ${offlineLoading?'disabled':''}>${icon('download',15)} Guardar todos</button>${offlineLoading?'<button class="button warning" data-action="library-offline-cancel">Cancelar</button>':''}</div></div><div class="info-bar">${icon('info',18)}<span>Ver un GIF no significa que tengas que reproducir ese ejercicio. No te fuerces si aumenta la molestia. En Pausa, las rutinas guiadas siguen una selección distinta y limitada de movimientos.</span></div>`}
function refreshLibrary({keepFocus=false}={}){if(page!=='biblioteca')return;const oldInput=el('librarySearch');const cursor=keepFocus&&oldInput?oldInput.selectionStart:null;const scroll=window.scrollY;render();if(keepFocus){const input=el('librarySearch');input.focus();if(cursor!==null)input.setSelectionRange(cursor,cursor);window.scrollTo(0,scroll)}}
function libraryDetail(id){const x=LIBRARY.find(x=>x.id===id);if(!x)return;librarySelected=x.id;libraryPreviewPlaying=mediaAnimated;modal(`<div class="modal-head"><div><div class="eyebrow">BIBLIOTECA · #${String(x.index).padStart(3,'0')}</div><h2 id="dialogTitle">${esc(x.title)}</h2><p>${esc(x.category)} · ${x.side==='bilateral'?'Ambos lados':x.side==='left'?'Lado izquierdo':'Lado derecho'}</p></div><button class="modal-close" data-action="close-modal" aria-label="Cerrar">${icon('close',17)}</button></div><div class="library-detail-visual"><img id="libraryDetailImage" src="${libraryPreviewPlaying?x.gif:x.poster}" width="640" height="640" alt="Animación ilustrativa: ${esc(x.title)}"><button type="button" class="media-motion-toggle" data-action="library-detail-toggle" aria-pressed="${libraryPreviewPlaying}">${icon(libraryPreviewPlaying?'pause':'play',14)} ${libraryPreviewPlaying?'Pausar GIF':'Reproducir GIF'}</button></div><div class="library-disclaimer"><strong>${icon('info',16)} Demostración visual pendiente de revisión profesional</strong><p>La secuencia representa un movimiento orientativo, pero no se han verificado clínicamente su biomecánica, amplitud ni adecuación para cada persona. No copies posiciones que provoquen molestias; evita forzar el cuello o la zona lumbar.</p></div><div class="dialog-actions"><button class="button secondary" data-action="close-modal">Cerrar</button><button class="button primary" data-action="library-next" data-id="${esc(x.id)}">Siguiente ejercicio ${icon('arrow',15)}</button></div>`,true)}
async function downloadLibraryOffline(){if(offlineLoading)return;if(!('caches'in window)){notifyToast('No disponible','Este navegador no admite almacenamiento offline.');return}offlineLoading=true;offlineAbort=false;const button=document.querySelector('[data-action="library-offline"]');if(button)button.disabled=true;const paths=LIBRARY.flatMap(x=>[x.poster,x.gif]);let successes=0;let failed=false;const progress=()=>{const n=el('offlineProgress');if(n)n.textContent=`Guardando ${successes} de ${paths.length} archivos${failed?' · Error de almacenamiento':''}…`;};progress();try{const cache=await caches.open('pausa-library-v1.2');for(const path of paths){if(offlineAbort)break;const url=new URL(path,location.href);const existing=await cache.match(url);if(!existing){const response=await fetch(url.href);if(!response.ok)throw Error(`HTTP ${response.status}: ${path}`);await cache.put(url,response)}successes++;if(successes%3===0)progress()};const n=el('offlineProgress');if(n)n.textContent=offlineAbort?`Detenido en ${successes}/${paths.length}; puedes reanudar después.`:`${paths.length} archivos disponibles offline en este navegador.`;if(!offlineAbort)notifyToast('Biblioteca lista','Las 112 animaciones y sus pósteres se guardaron para uso sin conexión.')}catch(err){failed=true;progress();notifyToast('Descarga incompleta','Revisa el espacio disponible o tu conexión; puedes reintentar.')}finally{offlineLoading=false;const b=document.querySelector('[data-action="library-offline"]');if(b)b.disabled=false;const cancel=document.querySelector('[data-action="library-offline-cancel"]');if(cancel)cancel.remove()}}
function activityPage(){const seven=Core.week(state.logs),t=statsToday(),max=Math.max(600,...seven.map(x=>x.seconds)),recent=[...state.logs].sort((a,b)=>b.at-a.at).slice(0,8),count=state.logs.length,recorded=Core.elapsedParts(Core.sumSeconds(state.logs));return `<section class="page-head"><div class="eyebrow">PEQUEÑOS LOGROS, GRAN CONSTANCIA</div><h1>Tu movimiento cuenta.</h1><p class="subheading">Un registro simple, sin metas imposibles ni juicios.</p></section>
 <div class="mini-stat-grid"><div class="stat-card"><span class="stat-icon">${icon('check',18)}</span><div class="stat-value">${count}</div><p class="stat-label">${count===1?'Sesión completada':'Sesiones completadas'}</p></div><div class="stat-card"><span class="stat-icon">${icon('clock',18)}</span><div class="stat-value">${recorded.value}<span>${recorded.unit}</span></div><p class="stat-label">Movimiento registrado</p></div><div class="stat-card"><span class="stat-icon">${icon('spark',18)}</span><div class="stat-value">${t.streak}<span>${t.streak===1?'día':'días'}</span></div><p class="stat-label">Racha actual</p></div></div>
 <div class="activity-layout"><section class="panel"><h3>Últimos 7 días</h3><p class="panel-subtitle">Minutos de sesiones que completaste en Pausa.</p><div class="bar-chart" aria-label="Gráfico semanal de minutos">${seven.map(day=>`<div class="bar-col"><div class="bar-track" title="${esc(day.key)}: ${Core.formatElapsed(day.seconds)}"><div class="bar-fill" style="height:${day.seconds===0?0:Math.max(6,day.seconds/max*100)}%"></div></div><div class="bar-day">${esc(day.label)}</div></div>`).join('')}</div><div class="activity-legend">● &nbsp;Los datos son aproximados y no miden todo tu movimiento diario.</div></section>
 <section class="panel"><h3>Actividad reciente</h3><p class="panel-subtitle">Solo las sesiones registradas en este dispositivo.</p>${recent.length?`<div class="timeline">${recent.map(l=>`<div class="timeline-item"><span class="timeline-icon">${icon('check',16)}</span><div><strong>${esc(l.name)}</strong><small>${dateFmt(l.at)} ${timeFmt(l.at)} · ${Core.formatElapsed(l.seconds)}</small></div>${Number.isInteger(l.beforePain)&&Number.isInteger(l.afterPain)?`<div class="time" title="Molestia autopercibida antes y después">${l.beforePain} → ${l.afterPain}</div>`:''}</div>`).join('')}</div>`:`<div class="empty-state">${icon('activity',26)}<p>Todavía no hay sesiones registradas.<br>Tu primera pausa puede ser hoy.</p><button class="button primary" data-action="detail" data-routine="seated">Comenzar una pausa</button></div>`}</section></div>`}
function settingsPage(){const r=state.reminders;return `<section class="page-head"><div class="eyebrow">TÚ DECIDES EL RITMO</div><h1>Un espacio a tu manera.</h1><p class="subheading">Tus preferencias y tu historial, guardados en este dispositivo.</p></section><div class="settings-grid"><div class="panel"><div class="panel-header"><span class="panel-icon">${icon('bell',20)}</span><div><h3>Recordatorios</h3><p class="panel-subtitle">Define cada cuánto necesitas cambiar de posición.</p></div></div><div class="setting-group"><label for="intervalInput">Frecuencia de las pausas</label><select id="intervalInput">${Core.VALID_INTERVALS.map(n=>`<option value="${n}" ${r.interval===n?'selected':''}>Cada ${n} minutos</option>`).join('')}</select><p class="setting-note">Como punto de partida puedes elegir 30 minutos. Ajusta según tu tolerancia y horario.</p></div><div class="setting-group"><label class="agent-checkbox"><input type="checkbox" id="scheduleToggle" ${r.scheduleEnabled?'checked':''}><span>Respetar mi horario laboral</span></label><div class="reminder-schedule-grid"><label for="scheduleStart">Desde<input id="scheduleStart" type="time" value="${r.start}"></label><label for="scheduleEnd">Hasta<input id="scheduleEnd" type="time" value="${r.end}"></label></div><label class="agent-checkbox"><input id="scheduleWeekdays" type="checkbox" ${r.weekdaysOnly?'checked':''}><span>Solo lunes a viernes</span></label><p class="setting-note">Los avisos esperan al siguiente horario permitido. Pausa debe estar abierta.</p></div><div class="settings-row"><div><strong>Jornada con recordatorios</strong><small>Funciona mientras la app está abierta</small></div><label class="toggle"><input type="checkbox" id="remindersToggle" aria-label="Activar recordatorios durante la jornada" ${r.enabled?'checked':''}><span></span></label></div><div class="settings-row"><div><strong>Notificaciones del navegador</strong><small id="permissionText">${typeof Notification==='undefined'?'No disponibles':Notification.permission==='granted'?'Permitidas':Notification.permission==='denied'?'Bloqueadas en el navegador':'Pedir autorización'}</small></div><button class="button secondary" data-action="permission" ${typeof Notification==='undefined'?'disabled':''}>${icon('bell',15)} Permitir</button></div><div class="settings-row"><div><strong>Probar un aviso</strong><small>Envía una prueba sin modificar tu próxima pausa.</small></div><button class="button secondary" data-action="test-notification" ${typeof Notification==='undefined'||Notification.permission!=='granted'?'disabled':''}>${icon('bell',15)} Probar aviso</button></div><div class="setting-note">Los navegadores pueden pausar temporizadores en pestañas inactivas. No hay avisos garantizados con la app cerrada.</div></div>
 <div><section class="panel" style="margin-bottom:20px"><div class="panel-header"><span class="panel-icon">${icon('lock',20)}</span><div><h3>Tu privacidad</h3><p class="panel-subtitle">El control de tus datos siempre es tuyo.</p></div></div><p class="setting-note">Tus sesiones y preferencias se guardan exclusivamente en el almacenamiento local del navegador. Borrar los datos del sitio también borra este historial.</p><div class="settings-row"><div><strong>Exportar mis datos</strong><small>Archivo JSON portable</small></div><button class="button secondary" data-action="export">${icon('download',16)} Exportar</button></div><div class="settings-row"><div><strong>Eliminar historial</strong><small>Acción irreversible</small></div><button class="button warning" data-action="clear-data">${icon('trash',16)} Borrar</button></div></section><div class="safety-box"><strong>${icon('warning',16)} Antes de empezar</strong>Ante dificultad para controlar vejiga o intestino, pérdida de sensibilidad genital/perineal o debilidad progresiva en las piernas, busca atención médica urgente. Si el dolor se irradia a una pierna o no mejora, consulta con un profesional.<p><button class="link-action" data-action="safety">Volver a revisar seguridad ${icon('arrow',13)}</button></p><a href="https://www.nhs.uk/conditions/back-pain/" target="_blank" rel="noopener noreferrer">Guía NHS sobre dolor lumbar ↗</a></div></div></div>`}
function render(){const labels={agente:'Mi guía',inicio:'Inicio',rutinas:'Mis rutinas',biblioteca:'Biblioteca',actividad:'Mi actividad',ajustes:'Preferencias'};el('breadcrumbCurrent').textContent=labels[page]||'Inicio';el('todayDate').textContent=new Intl.DateTimeFormat('es-PE',{weekday:'long',day:'numeric',month:'long'}).format(new Date());
 const html=page==='agente'?window.PausaAgentUI.render():page==='inicio'?home():page==='rutinas'?routinesPage():page==='biblioteca'?libraryPage():page==='actividad'?activityPage():settingsPage();el('appContent').innerHTML=html;document.body.dataset.page=page;
 document.querySelectorAll('[data-nav]').forEach(b=>{b.classList.toggle('active',b.dataset.nav===page);if(b.matches('.nav-item,.mobile-nav-item')){if(b.dataset.nav===page)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')}});
 document.querySelectorAll('.ico[data-icon]').forEach(node=>node.innerHTML=icon(node.dataset.icon,19));
}
function setPage(value){if(!['inicio','agente','rutinas','biblioteca','actividad','ajustes'].includes(value))return;page=value;history.replaceState(null,'','#'+value);render();el('appContent').focus({preventScroll:true});window.scrollTo({top:0,behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}
let modalReturnFocus=null;
function modal(html,wide=false){if(!activeModal)modalReturnFocus=document.activeElement;activeModal='open';document.querySelector('.app-layout').inert=true;el('mobileNav').inert=true;document.body.style.overflow='hidden';el('modalRoot').innerHTML=`<section class="dialog ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="dialogTitle">${html}</section>`;const first=el('modalRoot').querySelector('button,input,select');if(first)first.focus();}
function closeModal(){activeModal='';el('modalRoot').innerHTML='';safetyAction=null;document.querySelector('.app-layout').inert=false;el('mobileNav').inert=false;document.body.style.overflow='';if(modalReturnFocus?.isConnected)modalReturnFocus.focus({preventScroll:true});else el('appContent').focus({preventScroll:true});}
function notifyToast(title,description,withActions=false){lastToast=title;el('toastRoot').innerHTML=`<div class="toast"><div class="toast-icon">${icon('bell',19)}</div><div><strong>${esc(title)}</strong><p>${esc(description)}</p>${withActions?`<div class="toast-actions"><button data-action="detail" data-routine="seated">Hacer pausa</button><button class="subtle" data-action="snooze">Recordar en 10 min</button></div>`:''}</div><button class="toast-close" data-action="close-toast" aria-label="Cerrar aviso">${icon('close',15)}</button></div>`}
function chooseSafety(cb,routineId){if(state.safety==='urgent'){showUrgent();return}if(state.safety==='unset'){safetyAction={callback:cb,routineId};showSafety();return}if(state.safety==='caution'&&['lumbar','strength'].includes(routineId)){showCaution();return}cb()}
function showCaution(){modal(`<div class="modal-head"><div><div class="eyebrow">MOVERSE CON PRECAUCIÓN</div><h2 id="dialogTitle">Prioriza una evaluación.</h2><p>Has indicado molestias persistentes o que pueden irradiar hacia una pierna.</p></div><button class="modal-close" data-action="close-modal" aria-label="Cerrar">${icon('close',17)}</button></div><div class="alert-box" style="margin-top:20px">Por prudencia, las rutinas de suelo y fortalecimiento no están habilitadas en este modo. Puedes probar movimiento muy suave y tolerable, como caminar, mientras solicitas consejo profesional. Detente si empeora.</div><div class="dialog-actions"><button class="button secondary" data-action="close-modal">Entendido</button><button class="button primary" data-action="detail" data-routine="seated">Ver pausa suave</button></div>`)}
function showSafety(){modal(`<div class="modal-head"><div><div class="eyebrow">ANTES DE MOVERTE</div><h2 id="dialogTitle">Primero, tu seguridad.</h2><p>Estas preguntas son orientativas y no constituyen un diagnóstico.</p></div><button class="modal-close" data-action="close-modal" aria-label="Cerrar">${icon('close',17)}</button></div><div class="preflight-options"><label class="option-card"><input type="radio" name="safety" value="ok" ${state.safety==='ok'?'checked':''}><span><strong>Sin otras señales de alarma</strong>No tengo síntomas preocupantes adicionales y puedo realizar movimientos suaves sin aumentar las molestias.</span></label><label class="option-card"><input type="radio" name="safety" value="caution" ${state.safety==='caution'?'checked':''}><span><strong>Dolor persistente o que baja a una pierna</strong>Necesito consejo profesional; evitaré cualquier ejercicio que empeore mis síntomas.</span></label><label class="option-card alert"><input type="radio" name="safety" value="urgent" ${state.safety==='urgent'?'checked':''}><span><strong>Tengo alguna señal de alarma</strong>Pérdida de control urinario o intestinal, adormecimiento en la zona genital/perineal o debilidad progresiva en las piernas.</span></label></div><p class="alert-box" id="safetyResult" style="display:none"></p><label class="checkline"><input type="checkbox" id="safetyConsent"> <span>Entiendo que debo detenerme si aumenta el dolor y que esta app no reemplaza atención médica.</span></label><div class="dialog-actions"><button class="button secondary" data-action="close-modal">Ahora no</button><button class="button primary" id="saveSafetyButton" data-action="save-safety">Continuar ${icon('arrow',15)}</button></div>`);
 el('modalRoot').querySelectorAll('input[name="safety"]').forEach(r=>r.addEventListener('change',()=>{let urgent=el('modalRoot').querySelector('input[name="safety"]:checked')?.value==='urgent';el('safetyResult').style.display=urgent?'block':'none';el('safetyResult').textContent=urgent?'No sigas una rutina con estos síntomas. Busca evaluación médica urgente en un servicio de emergencias.':''}));
}
function saveSafety(){const selected=el('modalRoot').querySelector('input[name="safety"]:checked')?.value;if(!selected){notifyToast('Selecciona una respuesta','Necesitamos saber si tienes síntomas de alarma.');return}if(!el('safetyConsent').checked){notifyToast('Confirma la indicación','Marca la casilla para continuar.');return}const pending=safetyAction;state.safety=selected;if(selected==='urgent'||(selected==='caution'&&state.session&&['lumbar','strength'].includes(state.session.routineId))){state.session=null;}persist();closeModal();render();if(selected==='urgent'){showUrgent();return}if(pending){chooseSafety(pending.callback,pending.routineId)}}
function showUrgent(){modal(`<div class="modal-head"><div><div class="eyebrow">PRIORIZA TU SALUD</div><h2 id="dialogTitle">No hagas ejercicios ahora.</h2><p>Has indicado signos que pueden requerir atención médica urgente.</p></div><button class="modal-close" data-action="close-modal" aria-label="Cerrar">${icon('close',17)}</button></div><div class="alert-box" style="margin-top:22px">Busca evaluación en un servicio de emergencias, especialmente si aparecen cambios de sensibilidad en genitales, pérdida de control de esfínteres o debilidad progresiva. No uses esta app para retrasar la consulta.</div><div class="dialog-actions"><button class="button secondary" data-action="close-modal">Entendido</button><button class="button warning" data-action="safety">Revisar respuesta</button></div>`)}
function showRoutine(id){const r=ROUTINES.find(x=>x.id===id);if(!r)return;
 modal(`<div class="modal-head"><div><div class="eyebrow">RUTINA GUIADA · ${duration(totalSeconds(r))}</div><h2 id="dialogTitle">${esc(r.name)}</h2><p>${esc(r.description)}</p></div><button class="modal-close" data-action="close-modal" aria-label="Cerrar">${icon('close',18)}</button></div><div class="modal-art">${visualExercise(r.ids[0])}</div><div class="summary-inline">${icon('clock',17)} ${duration(totalSeconds(r))} &nbsp; · &nbsp; ${r.ids.length} movimientos &nbsp; · &nbsp; ${esc(r.level)}</div><ul class="modal-list">${r.ids.map(id=>`<li>${esc(EXERCISES[id].name)} <span class="muted">· ${EXERCISES[id].seconds}s</span></li>`).join('')}</ul><div class="divider"></div><fieldset class="setting-group checkin-group"><legend>Opcional: ¿cómo sientes la zona lumbar ahora? (0 = ninguna molestia; 10 = máxima imaginable)</legend><div class="checkin-scale">${Array.from({length:11},(_,i)=>`<label><input name="beforePain" type="radio" value="${i}"><span>${i}</span></label>`).join('')}</div><div class="checkin-caption"><span>Sin molestia</span><span>Máxima imaginable</span></div></fieldset><div class="dialog-actions"><button class="button secondary" data-action="close-modal">Más tarde</button><button class="button primary" data-action="start" data-routine="${r.id}">${icon('play',15)} Comenzar ahora</button></div>`,true)
}
function startRoutine(id){if(state.safety==='urgent'){showUrgent();return}if(state.safety==='caution'&&['lumbar','strength'].includes(id)){showCaution();return}const r=ROUTINES.find(x=>x.id===id);if(!r)return;
 if(state.session){notifyToast('Ya hay una sesión activa','Termina o abandona la sesión anterior.');showSession();return}
 const selected=el('modalRoot').querySelector('input[name="beforePain"]:checked');const beforePain=selected?Number(selected.value):null;
 state.session={routineId:id,index:0,remaining:EXERCISES[r.ids[0]].seconds,paused:false,endAt:now()+EXERCISES[r.ids[0]].seconds*1000,elapsedSeconds:0,beforePain};persist();showSession();}
function showSession(){const s=state.session;if(!s)return;const r=ROUTINES.find(x=>x.id===s.routineId);if(!r){state.session=null;persist();return}if(s.index>=r.ids.length){finishSession();return}const e=EXERCISES[r.ids[s.index]];const remain=s.paused?s.remaining:Math.max(0,Math.ceil((s.endAt-now())/1000));
 modal(`<div class="session-screen"><div class="session-head"><strong>${esc(r.name)}</strong><span>Movimiento ${s.index+1} de ${r.ids.length}</span><button class="modal-close" data-action="exit-session" aria-label="Salir de la sesión">${icon('close',17)}</button></div><div class="session-progress"><span style="width:${s.index/r.ids.length*100}%"></span></div><div class="session-pose">${visualExercise(e.id)}</div><h2 id="dialogTitle">${esc(e.name)}</h2><p class="session-description">${esc(e.subtitle)} · ${esc(e.place)}</p><div id="sessionTimer" class="session-clock" aria-label="Tiempo restante">${Core.formatClock(remain)}</div><p class="session-tip">${icon('info',14)} ${esc(e.tip)}</p><ol class="session-steps">${e.steps.map(step=>`<li>${esc(step)}</li>`).join('')}</ol><div class="session-buttons"><button class="button secondary" data-action="session-pause">${icon(s.paused?'play':'pause',16)} ${s.paused?'Continuar':'Pausar'}</button><button class="button primary" data-action="session-next">${s.index===r.ids.length-1?'Finalizar':'Siguiente'} ${icon('arrow',15)}</button></div></div>`,false)
}
function advanceSession(){const s=state.session;if(!s)return;const r=ROUTINES.find(x=>x.id===s.routineId);if(!r)return;const current=EXERCISES[r.ids[s.index]];const remaining=s.paused?s.remaining:Math.max(0,Math.ceil((s.endAt-now())/1000));s.elapsedSeconds=(s.elapsedSeconds||0)+Math.max(0,current.seconds-remaining);const next=s.index+1;if(next>=r.ids.length){finishSession();return}s.index=next;s.remaining=EXERCISES[r.ids[next]].seconds;s.paused=false;s.endAt=now()+s.remaining*1000;persist();showSession()}
function toggleSession(){const s=state.session;if(!s)return;if(s.paused){s.paused=false;s.endAt=now()+s.remaining*1000}else{s.remaining=Math.max(0,Math.ceil((s.endAt-now())/1000));s.paused=true;s.endAt=0}persist();showSession()}
function exitSession(){if(!state.session){closeModal();return}if(window.confirm('¿Abandonar esta sesión? No se registrará como completada.')){state.session=null;persist();closeModal();render()}}
function finishSession(){const s=state.session;if(!s)return;const r=ROUTINES.find(x=>x.id===s.routineId);if(!r)return;const actualSeconds=Math.min(totalSeconds(r),Math.floor(s.elapsedSeconds||0));if(actualSeconds<10){state.session=null;if(state.reminders.enabled){state.reminders.pending=false;state.reminders.nextDueAt=Core.nextAllowedReminder(now()+state.reminders.interval*60000,state.reminders);}persist();closeModal();render();notifyToast('Secuencia terminada','No se registró tiempo porque se omitieron casi todos los movimientos.');return;}const log={id:`${now()}-${Math.random().toString(36).slice(2,8)}`,routineId:r.id,name:r.name,seconds:actualSeconds,at:now(),beforePain:s.beforePain,afterPain:null};state.logs.push(log);state.logs=state.logs.slice(-1000);state.session=null;
 if(state.reminders.enabled){state.reminders.pending=false;state.reminders.nextDueAt=Core.nextAllowedReminder(now()+state.reminders.interval*60000,state.reminders);el('toastRoot').innerHTML=''}persist();render();showFinished(log.id)}
function showFinished(logId){const l=state.logs.find(x=>x.id===logId);if(!l)return;modal(`<div class="complete-mark">${icon('check',34)}</div><h2 class="finished-title" id="dialogTitle">¡Bien hecho, te moviste!</h2><p class="finished-copy">Completaste <b>${esc(l.name)}</b> · ${Core.formatElapsed(l.seconds)}. Una pausa más para tu bienestar.</p><div class="divider"></div><fieldset class="setting-group checkin-group"><legend>Opcional: ¿cómo sientes la espalda después? (0–10)</legend><div class="checkin-scale">${Array.from({length:11},(_,i)=>`<label><input name="afterPain" type="radio" value="${i}"><span>${i}</span></label>`).join('')}</div><p class="setting-note">Autorreporte subjetivo; estos valores no son un diagnóstico ni una medida de recuperación clínica.</p></fieldset><div class="dialog-actions"><button class="button secondary" data-action="close-modal">Omitir</button><button class="button primary" data-action="save-after" data-id="${l.id}">Guardar y finalizar ${icon('check',15)}</button></div>`)}
function toggleReminders(enabled){state.reminders.enabled=enabled;state.reminders.pending=false;state.reminders.nextDueAt=enabled?Core.nextAllowedReminder(now()+state.reminders.interval*60000,state.reminders):0;persist();el('toastRoot').innerHTML='';render();notifyToast(enabled?'Recordatorios activados':'Jornada detenida',enabled?`Te avisaré cada ${state.reminders.interval} minutos mientras la app esté abierta.`:'Puedes volver a activarlos cuando quieras.')}
function snooze(){state.reminders.pending=false;state.reminders.nextDueAt=Core.nextAllowedReminder(now()+10*60000,state.reminders);state.reminders.enabled=true;persist();el('toastRoot').innerHTML='';render();notifyToast('Pausa pospuesta','Volveré a recordártelo en 10 minutos, si la app sigue abierta.')}
function showSystemReminder(test=false){
 if(typeof Notification==='undefined'||Notification.permission!=='granted')return Promise.resolve(false);
 const title=test?'Pausa · Notificación de prueba':'Pausa · Es momento de moverte';
 const options={
  body:test?'Comprueba que puedes ver este aviso y volver a Pausa al pulsarlo.':'Puedes moverte sentado o ponerte de pie si lo prefieres.',
  icon:'assets/icon-192.png',tag:test?'pausa-notification-test':'pausa-reminder'
 };
 const fallback=()=>{try{new Notification(title,options);return true}catch{return false}};
 if('serviceWorker'in navigator&&typeof navigator.serviceWorker.getRegistration==='function'){
  return navigator.serviceWorker.getRegistration().then(reg=>{
   if(reg&&typeof reg.showNotification==='function')return reg.showNotification(title,options).then(()=>true).catch(fallback);
   return fallback();
  }).catch(fallback);
 }
 return Promise.resolve(fallback());
}
let reminderClaimInFlight=false;
function claimDueReminder(){
 let snapshot;
 try{snapshot=JSON.parse(localStorage.getItem(STORAGE)||'null')}catch{}
 const r=Core.normalize({reminders:snapshot?.reminders||state.reminders}).reminders;
 state.reminders=r;
 const moment=now();
 if(!r.enabled||r.pending||r.nextDueAt<=0||r.nextDueAt>moment)return;
 const allowed=Core.nextAllowedReminder(moment,r);
 const due=allowed<=moment;
 if(due)r.pending=true;else r.nextDueAt=allowed;
 if(snapshot&&typeof snapshot==='object'){
  snapshot.reminders=r;
  try{localStorage.setItem(STORAGE,JSON.stringify(snapshot))}catch{persist()}
 }else persist();
 if(!due){if(page==='inicio')render();return}
 if(!state.session){render();notifyToast('Es momento de una pausa','Llevas un rato trabajando. Puedes moverte suavemente sin levantarte.',true)}
 else notifyToast('Una pausa pendiente','Termina tu sesión; los recordatorios se reiniciarán.',false);
 if(typeof Notification!=='undefined'&&Notification.permission==='granted'&&now()-lastDueNotificationAt>60000){
  lastDueNotificationAt=now();showSystemReminder();
 }
}
function coordinateDueReminder(){
 if(reminderClaimInFlight)return;
 reminderClaimInFlight=true;
 const locks=navigator.locks;
 let operation;
 try{
  operation=locks?.request?locks.request('pausa-reminder-claim',{ifAvailable:true},lock=>{if(lock)claimDueReminder()}):Promise.resolve().then(claimDueReminder);
 }catch{operation=Promise.resolve().then(claimDueReminder)}
 Promise.resolve(operation).catch(()=>{}).finally(()=>{reminderClaimInFlight=false});
}
function nextTick(){const s=state.session;
 if(s&&!s.paused){const left=Math.max(0,Math.ceil((s.endAt-now())/1000));const countdown=el('sessionTimer');if(countdown)countdown.textContent=Core.formatClock(left);if(left<=0)advanceSession()}
 const r=state.reminders;
 if(r.enabled&&!r.pending&&r.nextDueAt<=now()&&r.nextDueAt>0)coordinateDueReminder();
 if(page==='inicio'){const count=el('countdown');if(count&&r.enabled){count.textContent=r.pending?'00:00':Core.formatClock(Math.ceil((r.nextDueAt-now())/1000))}}
}
function exportData(){const payload={app:'Pausa',version:1,exportedAt:new Date().toISOString(),logs:state.logs,reminders:{interval:state.reminders.interval}};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`pausa-datos-${Core.dateKey(now())}.json`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2500)}
function handleAction(button){const action=button.dataset.action;switch(action){
 case 'agent-start':window.PausaAgentUI.start();break;
 case 'agent-pause':window.PausaAgentUI.pause();break;
 case 'agent-next':window.PausaAgentUI.next();break;
 case 'agent-end':window.PausaAgentUI.end();break;
 case 'detail':chooseSafety(()=>showRoutine(button.dataset.routine),button.dataset.routine);break;
 case 'start':startRoutine(button.dataset.routine);break;
 case 'close-modal':closeModal();break;
 case 'save-safety':saveSafety();break;
 case 'safety':safetyAction=null;showSafety();break;
 case 'session-pause':toggleSession();break;
 case 'toggle-media':toggleMedia();break;
 case 'library-detail':libraryDetail(button.dataset.id);break;
 case 'library-toggle':{const id=button.dataset.id;const x=LIBRARY.find(x=>x.id===id);if(!x)return;if(!mediaAnimated)mediaAnimated=true;if(libraryPlaying.has(id))libraryPlaying.delete(id);else libraryPlaying.add(id);const card=button.closest('.library-card');if(card)card.outerHTML=libraryCard(x);break;}
 case 'library-pause-all':libraryPlaying.clear();if(page==='biblioteca')refreshLibrary();break;
 case 'library-clear':libraryQuery='';libraryFilter='Todas';librarySide='todos';libraryShown=24;libraryPlaying.clear();refreshLibrary();break;
 case 'library-more':libraryShown+=24;refreshLibrary();break;
 case 'library-detail-toggle':{const x=LIBRARY.find(x=>x.id===librarySelected);if(!x)break;libraryPreviewPlaying=!libraryPreviewPlaying;el('libraryDetailImage').src=libraryPreviewPlaying?x.gif:x.poster;button.setAttribute('aria-pressed',String(libraryPreviewPlaying));button.innerHTML=`${icon(libraryPreviewPlaying?'pause':'play',14)} ${libraryPreviewPlaying?'Pausar GIF':'Reproducir GIF'}`;break;}
 case 'library-next':{const i=LIBRARY.findIndex(x=>x.id===button.dataset.id);libraryDetail(LIBRARY[(i+1)%LIBRARY.length].id);break;}
 case 'library-offline':downloadLibraryOffline();break;
 case 'library-offline-cancel':offlineAbort=true;break;
 case 'session-next':advanceSession();break;
 case 'exit-session':exitSession();break;
 case 'save-after':{const log=state.logs.find(l=>l.id===button.dataset.id);const after=el('modalRoot').querySelector('input[name="afterPain"]:checked');if(log&&after)log.afterPain=Number(after.value);persist();closeModal();render();break}
 case 'reminders-on':toggleReminders(true);break;
 case 'reminders-off':toggleReminders(false);break;
 case 'snooze':snooze();break;
 case 'close-toast':el('toastRoot').innerHTML='';break;
 case 'permission':if(typeof Notification!=='undefined'){Notification.requestPermission().then(value=>{render();notifyToast(value==='granted'?'Avisos permitidos':'Avisos no permitidos',value==='granted'?'Verás avisos si la app permanece abierta.':'Puedes cambiar los permisos desde tu navegador.')}).catch(()=>notifyToast('Permiso no disponible','Comprueba que la app se sirva por HTTPS o localhost.'))}break;
 case 'test-notification':showSystemReminder(true).then(sent=>{
  notifyToast(sent?'Aviso de prueba enviado':'No se pudo mostrar el aviso',sent?'Comprueba las notificaciones de tu sistema y pulsa el aviso para volver a Inicio.':'Revisa los permisos y ajustes de notificaciones del navegador y de Windows.');
 });break;
 case 'export':exportData();notifyToast('Descarga iniciada','El archivo contiene tu historial local de sesiones.');break;
 case 'clear-data':if(window.confirm('¿Eliminar TODAS las sesiones registradas? Esta acción no se puede deshacer.')){state.logs=[];persist();render();notifyToast('Historial eliminado','Tu configuración de recordatorios se conservó.')}break;
 default:break;
}}
document.addEventListener('click',event=>{const nav=event.target.closest('[data-nav]');if(nav){event.preventDefault();setPage(nav.dataset.nav);return}const f=event.target.closest('[data-filter]');if(f){filter=f.dataset.filter;render();return}const lf=event.target.closest('[data-library-filter]');if(lf){libraryFilter=lf.dataset.libraryFilter;libraryShown=24;libraryPlaying.clear();refreshLibrary();return}const action=event.target.closest('[data-action]');if(action){event.preventDefault();handleAction(action)}});
document.addEventListener('input',event=>{if(event.target.id==='librarySearch'){libraryQuery=event.target.value;libraryShown=24;libraryPlaying.clear();refreshLibrary({keepFocus:true})}});
document.addEventListener('change',event=>{if(event.target.id==='librarySide'){librarySide=event.target.value;libraryShown=24;libraryPlaying.clear();refreshLibrary();return}if(event.target.id==='intervalInput'){const n=Number(event.target.value);if(Core.VALID_INTERVALS.includes(n)){state.reminders.interval=n;if(state.reminders.enabled){state.reminders.nextDueAt=Core.nextAllowedReminder(now()+n*60000,state.reminders);state.reminders.pending=false}persist();render();notifyToast('Frecuencia actualizada',`Tu próximo recordatorio será en ${n} minutos.`)}}else if(event.target.id==='remindersToggle'){toggleReminders(event.target.checked)}
 else if(['scheduleToggle','scheduleStart','scheduleEnd','scheduleWeekdays'].includes(event.target.id)){
  const start=el('scheduleStart')?.value||state.reminders.start,end=el('scheduleEnd')?.value||state.reminders.end;
  if(start>=end){notifyToast('Horario inválido','El inicio debe ser anterior al fin.');render();return;}
  state.reminders.scheduleEnabled=!!el('scheduleToggle')?.checked;
  state.reminders.start=start;state.reminders.end=end;state.reminders.weekdaysOnly=!!el('scheduleWeekdays')?.checked;
  if(state.reminders.enabled&&!state.reminders.pending)state.reminders.nextDueAt=Core.nextAllowedReminder(now()+state.reminders.interval*60000,state.reminders);
  persist();render();notifyToast('Horario actualizado','Los avisos seguirán este horario mientras Pausa esté abierta.');
 }});
document.addEventListener('keydown',event=>{if(event.key==='Tab'&&activeModal){const nodes=[...el('modalRoot').querySelectorAll('button:not(:disabled),input:not(:disabled),select,textarea,a[href]')].filter(n=>n.getClientRects().length);const first=nodes[0],last=nodes[nodes.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus()}}if(event.key==='Escape'&&activeModal){if(window.PausaAgentUI?.isSessionActive()){window.PausaAgentUI.end();return}if(state.session)exitSession();else closeModal()}});
document.addEventListener('visibilitychange',()=>{if(!document.hidden)nextTick()});
window.addEventListener('storage',event=>{if(event.key===STORAGE){try{
 const latest=Core.normalize(JSON.parse(event.newValue||'null'));
 state.reminders=latest.reminders;state.logs=latest.logs;state.safety=latest.safety;
 if(!state.session)state.session=latest.session;
 render();
}catch{}}});
if(state.safety==='urgent'&&state.session){state.session=null;persist();}if(page==='agente')page='inicio';render();if(state.session){notifyToast('Tienes una sesión pendiente','Puedes continuar desde donde la dejaste.');el('toastRoot').querySelector('.toast-actions')?.remove();const holder=el('toastRoot').querySelector('.toast>div:nth-child(2)');if(holder)holder.insertAdjacentHTML('beforeend','<div class="toast-actions"><button data-action="resume">Reanudar sesión</button><button data-action="discard-session" class="subtle">Descartar</button></div>')}
window.addEventListener('click',event=>{const action=event.target.closest('[data-action]');if(!action)return;if(action.dataset.action==='resume'){el('toastRoot').innerHTML='';showSession()}else if(action.dataset.action==='discard-session'){state.session=null;persist();el('toastRoot').innerHTML='';render()}});
if('serviceWorker'in navigator){
 navigator.serviceWorker.addEventListener('message',event=>{
  if(event.data?.type!=='pausa-reminder-open')return;
  setPage('inicio');
  if(state.reminders.pending)notifyToast('Tu pausa está lista','Puedes empezar ahora o posponerla diez minutos.',true);
 });
}
setInterval(nextTick,1000);nextTick();
if('serviceWorker'in navigator&&location.protocol!=='file:'){
 navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'}).then(reg=>{
  // Force a version check on navigation, including users returning to an old tab.
  reg.update().catch(()=>{});
 }).catch(()=>{});
}
